def minEncodedLength(s):
    n = len(s)
    dp = [10 ** 9] * (n + 1)
    dp[0] = 0
    for j in range(n):
        if dp[j] + 1 < dp[j + 1]:
            dp[j + 1] = dp[j] + 1
        t = s[j:]
        m = len(t)
        pi = [0] * m
        k = 0
        for i in range(1, m):
            while k and t[i] != t[k]:
                k = pi[k - 1]
            if t[i] == t[k]:
                k += 1
            pi[i] = k
        for L in range(2, m + 1):
            d = L - pi[L - 1]
            if L % d == 0 and L // d >= 2:
                c = dp[j] + d + len(str(L // d))
                if c < dp[j + L]:
                    dp[j + L] = c
    return dp[n]
